function Footer() {
  return (
    <footer className="text-muted py-5 border-top mt-5 bg-dark">
      <div className="container">
        <p className="float-end mb-1">
            <a href="#">Back to top</a>
        </p>
        <p className="mb-1">© 2025 SpringBoard</p>
        <p className="mb-0">New to our LMS? <a href="#">Visit the homepage</a> or read our <a href="#">getting started guide</a>.</p>
      </div>
    </footer>
  );
}

export default Footer;
